@pytest.mark.parametrize("sid,key,heading,sentence,expect", S,
                         ids=[(s.values if hasattr(s, "values") else s)[0] for s in S])
def test_rv4_corpus(sid, key, heading, sentence, expect):
    findings, allowed, language = CTX[key]
    res = verify_narrative(f"## {heading}\n\n{sentence}", findings, allowed, language)
    assert ("remove" if res.removed else "keep") == expect


