@pytest.mark.parametrize("key,prefix,sentence,expect", PROBES)
def test_second_pass_probes(key, prefix, sentence, expect):
    findings, allowed, language = CTX[key]
    heading = prefix if prefix in ("Executive Summary", "Yönetici Özeti", "Methods") else next(
        s.heading for s in findings.sections if s.heading.startswith(prefix))
    res = verify_narrative(f"## {heading}\n\n{sentence}", findings, allowed, language)
    assert ("remove" if res.removed else "keep") == expect
